<?php
namespace App\\Http\\Controllers;use App\\Models\\{Product,Category,Order,User};use Illuminate\\Http\\Request;use Illuminate\\Support\\Str;class AdminController extends Controller{public function dashboard(){return view('admin.dashboard',['products'=>Product::count(),'orders'=>Order::count(),'customers'=>User::where('role','customer')->count(),'pending'=>Order::where('status','pending')->count(),'recent'=>Order::with('user')->latest()->take(8)->get()]);}public function products(){return view('admin.products',['products'=>Product::with('category')->latest()->paginate(15),'categories'=>Category::orderBy('name')->get()]);}public function storeProduct(Request $r){$d=$r->validate(['name'=>'required|string|max:180','category_id'=>'required|exists:categories,id','description'=>'nullable|string','price_usd'=>'required|numeric|min:0','price_cdf'=>'required|numeric|min:0','stock'=>'required|integer|min:0','image'=>'nullable|image|max:2048','condition'=>'required|in:new,used']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));if($r->hasFile('image'))$d['image']=$r->file('image')->store('products','public');Product::create($d+['is_active'=>true]);return back()->with('success','Produit créé.');}public function deleteProduct(Product $product){$product->update(['is_active'=>false]);return back()->with('success','Produit désactivé.');}public function orders(){return view('admin.orders',['orders'=>Order::with('user')->latest()->paginate(20)]);}public function updateOrder(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:pending,confirmed,processing,shipped,delivered,cancelled','payment_status'=>'required|in:pending,paid,failed,refunded']);$order->update($d);$order->payment()->update(['status'=>$d['payment_status'],'paid_at'=>$d['payment_status']==='paid'?now():null]);return back()->with('success','Commande mise à jour.');}}
